DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='leads' AND column_name='county') THEN
    ALTER TABLE leads ADD COLUMN county text DEFAULT '';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='leads' AND column_name='phone') THEN
    ALTER TABLE leads ADD COLUMN phone text DEFAULT '';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='leads' AND column_name='source') THEN
    ALTER TABLE leads ADD COLUMN source text DEFAULT 'manual';
  END IF;
END $$; SELECT 1;

parameters.jsCode:
const counties = [
  'Greater London','Kent','Surrey','Hertfordshire','Essex',
  'Suffolk','Norfolk','Leicestershire','Derbyshire','West Midlands',
  'Worcestershire','West Yorkshire','North Yorkshire','Lancashire',
  'Greater Manchester','Cheshire','County Durham','Northumberland','Dorset','Hampshire',
  'Oxfordshire','Cambridgeshire','Buckinghamshire','Berkshire','Devon',
  'Cornwall','Somerset','Gloucestershire','Wiltshire','Shropshire'
];
const venueTypes = [
  {q:'village hall hire',             t:'Village Hall'},
  {q:'community centre room hire',    t:'Community Centre'},
  {q:'sports club function room',     t:'Sports Club'},
  {q:'event venue hire',              t:'Event Venue'},
  {q:'church hall hire',              t:'Community Centre'},
  {q:'social club venue hire',        t:'Sports Club'},
  {q:'hotel function room hire',      t:'Hotel'},
  {q:'working mens club hire',        t:'Sports Club'}
];

// Rotate county by day-of-month so each day targets a different area
const county = counties[new Date().getDate() % counties.length];

return venueTypes.map(v => ({
  json: {
    query:            v.q + ' ' + county,
    county:           county,
    venue_type_label: v.t
  }
}));

const item = $input.item.json;

// Get county and venue_type from upstream Generate Searches node
let genItem = {};
try { genItem = $('Generate Searches').item.json; } catch(e) {}
const county = String(genItem.county || item.county || 'England');
const vtype  = String(genItem.venue_type_label || item.venue_type_label || 'Community Venue');

// Google Places API returns: { places: [ { displayName, formattedAddress, websiteUri, nationalPhoneNumber, id } ] }
const places = Array.isArray(item.places) ? item.places : [];

if (places.length === 0) {
  console.log('No places returned for query:', genItem.query || 'unknown');
  return [];
}

// Chains/irrelevant venues to skip
const SKIP = /tesco|asda|sainsbury|morrisons|costa|starbucks|mcdonalds|pizza|kfc|nando|greggs|boots|lidl|aldi|amazon/i;

const results = [];
for (const p of places) {
  const name    = (p.displayName && p.displayName.text) ? p.displayName.text.trim() : '';
  const address = p.formattedAddress || '';
  const website = p.websiteUri || '';
  const phone   = p.nationalPhoneNumber || '';
  const placeId = p.id || '';

  if (!name || name.length < 3) continue;
  if (SKIP.test(name)) continue;

  results.push({
    json: {
      venue_name:  name.substring(0, 120),
      website_url: website,
      phone:       phone,
      venue_type:  vtype,
      county:      county,
      notes:       ('Google Maps · ' + county + (address ? ' · ' + address : '')).substring(0, 255),
      place_id:    placeId,
      source:      'google_maps'
    }
  });
}

console.log('Parsed', results.length, 'venues from Google Maps for', vtype, 'in', county);
return results;

